const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`));
  page.on('console', message => { if (message.type() === 'error') errors.push(`console: ${message.text()}`); });
  const response = await page.goto('http://127.0.0.1:3000/', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1200);
  const state = await page.evaluate(() => ({ title: document.title, ready: document.readyState, canvas: !!document.querySelector('canvas#game'), canvasSize: [document.querySelector('canvas#game')?.width, document.querySelector('canvas#game')?.height], body: document.body.innerText.slice(0, 100) }));
  console.log(JSON.stringify({ status: response?.status(), state, errors }, null, 2));
  await browser.close();
  if (!response?.ok() || !state.canvas || errors.length) process.exitCode = 1;
})().catch(error => { console.error(error); process.exitCode = 1; });
